+function validateListConversationsMessage(message: Record<string, unknown>): ValidationResult {
+  const limit = message.limit;
+  if (limit !== undefined && (!Number.isInteger(limit) || (limit as number) < 1 || (limit as number) > 200)) {
+    return {valid: false, error: 'list_conversations limit must be an integer from 1 to 200'};
+  }
+
+  if (message.before === undefined)
+    return {valid: true, data: {type: 'list_conversations', limit: limit as number | undefined}};
+  if (typeof message.before !== 'object' || message.before === null) {
+    return {valid: false, error: 'list_conversations before must be an object'};
+  }
+
+  const before = message.before as Record<string, unknown>;
+  if (typeof before.sessionId !== 'string' || before.sessionId.length < 1 || before.sessionId.length > 128) {
+    return {valid: false, error: 'list_conversations before.sessionId must be 1-128 characters'};
+  }
+  if (typeof before.updatedAt !== 'string' || Number.isNaN(Date.parse(before.updatedAt))) {
+    return {valid: false, error: 'list_conversations before.updatedAt must be a valid date'};
+  }
+
+  return {
+    valid: true,
+    data: {
+      type: 'list_conversations',
+      limit: limit as number | undefined,
+      before: {sessionId: before.sessionId, updatedAt: before.updatedAt},
+    },
+  };
+}
+
 function isValidTimestamp(value: unknown): value is string | number {
